import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.CHeM0PsO.js";const d=JSON.parse('{"title":"LPA 条款图谱：有限合伙协议交互式知识地图","description":"","frontmatter":{"title":"LPA 条款图谱：有限合伙协议交互式知识地图","date":"2026-08-03T00:00:00.000Z","category":"法律知识产品","summary":"将有限合伙协议拆成 38 个结构化篇章，以规则、分歧、起草和法规依据组织成可搜索、可批注的交互式阅读工具。","number":"06","status":"开源作品","language":"HTML","license":"未标注","github":"https://github.com/Hellyai/lpa-clause-map","demo":"https://hellyai.github.io/lpa-clause-map/","capabilities":["38 个 LPA 结构化篇章","关键词搜索、模块筛选与法规交叉检索","本地批注、阅读笔记与 Markdown 导出"],"tags":["LPA","私募基金","条款图谱","法律产品","GitHub Pages"]},"headers":[],"relativePath":"work/lpa-clause-map.md","filePath":"work/lpa-clause-map.md","lastUpdated":1788339898000}'),i={name:"work/lpa-clause-map.md"};function o(s,a,p,h,n,u){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="lpa-条款图谱-有限合伙协议交互式知识地图" tabindex="-1">LPA 条款图谱：有限合伙协议交互式知识地图 <a class="header-anchor" href="#lpa-条款图谱-有限合伙协议交互式知识地图" aria-label="Permalink to &quot;LPA 条款图谱：有限合伙协议交互式知识地图&quot;">​</a></h1><p>LPA 条款图谱是一款面向私募基金入门者和法律从业者的交互式阅读、审阅与起草辅助工具。它不按合同文字顺序机械展示内容，而是沿基金设立、募集、投资、管理、分配、退出和清算的生命周期重新组织条款关系。</p><p><a href="https://hellyai.github.io/lpa-clause-map/" target="_blank" rel="noreferrer">在线体验 →</a> · <a href="https://github.com/Hellyai/lpa-clause-map" target="_blank" rel="noreferrer">查看 GitHub 仓库 →</a></p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>有限合伙协议通常篇幅很长，且条款之间存在大量交叉引用。初次接触时，读者容易看见单个条款，却难以理解它在基金整体机制中的位置，以及相关权利义务如何互相影响。</p><h2 id="核心体验" tabindex="-1">核心体验 <a class="header-anchor" href="#核心体验" aria-label="Permalink to &quot;核心体验&quot;">​</a></h2><ul><li>将 LPA 拆分为 38 个结构化篇章；</li><li>每项条款分别展示基本规则、审核要点、常见分歧、起草落点和规则依据；</li><li>支持搜索管理费、收益分配、后续募集、关键人士、回拨等主题；</li><li>可以按基金生命周期模块筛选内容；</li><li>法规按钮跳转公开权威来源，便于核对原文；</li><li>支持个人批注，并能集中回看或导出 Markdown。</li></ul><h2 id="内容范围" tabindex="-1">内容范围 <a class="header-anchor" href="#内容范围" aria-label="Permalink to &quot;内容范围&quot;">​</a></h2><p>项目覆盖基金设立与期限、合伙人及出资、后续募集、违约处理、管理人与治理、投资范围和限制、管理费与费用、收益分配与回拨、入伙退伙和权益转让、信息披露、托管、反洗钱、关键人士、解散与清算等核心主题。</p><h2 id="我的设计判断" tabindex="-1">我的设计判断 <a class="header-anchor" href="#我的设计判断" aria-label="Permalink to &quot;我的设计判断&quot;">​</a></h2><p>法律知识产品不应只把纸面目录搬到网页上。条款需要同时回答四个问题：它解决什么问题、审阅时争议在哪里、起草应落到哪里、依据能否被核验。交互设计则应帮助读者从整体结构进入细节，并保留自己的阅读痕迹。</p><h2 id="隐私与更新边界" tabindex="-1">隐私与更新边界 <a class="header-anchor" href="#隐私与更新边界" aria-label="Permalink to &quot;隐私与更新边界&quot;">​</a></h2><p>批注只保存在当前浏览器本地，不会上传到 GitHub。项目内容更新基准日为 <strong>2026 年 7 月 31 日</strong>；法规、自律规则和地方登记口径可能变化，使用时仍应核验最新规定。本工具属于学习、审阅和起草辅助材料，不构成针对具体基金的法律意见。</p>',13)])])}const m=e(i,[["render",o]]);export{d as __pageData,m as default};
